@namespace sv_28002f52e1a74575957413a9d07708f6.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="reference-entry">
            <div class="entry-header">
                <h4>Reference @(index + 1)</h4>
                @if (References.Count > 2)
                {
                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@References[index].Name"
                           @onchange="e => { References[index].Name = e.Value?.ToString() ?? string.Empty; }" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@References[index].Relationship"
                           @onchange="e => { References[index].Relationship = e.Value?.ToString() ?? string.Empty; }" />
                </div>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@References[index].Email"
                           @onchange="e => { References[index].Email = e.Value?.ToString() ?? string.Empty; }" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@References[index].Phone"
                           @onchange="e => { References[index].Phone = e.Value?.ToString() ?? string.Empty; }" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All fields are required for each reference.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

